import React, { useState, useCallback } from 'react';
import { View, Text, StyleSheet, TouchableOpacity, Dimensions, TextProps } from 'react-native';

// Define the props interface for clarity and TypeScript safety
interface ExpandableTextProps extends TextProps {
  text: string;
  // The maximum number of lines to show before truncating (default to 1)
  maxLines?: number;
}

/**
 * A production-ready component to display text that expands on click.
 * It shows only the first 'maxLines' (default 1) and appends "See more".
 * Clicking reveals the full text.
 */
const ExpandableText: React.FC<ExpandableTextProps> = ({
  text,
  maxLines = 1,
  style,
  ...rest
}) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [lineCount, setLineCount] = useState(1); // Start assuming it's one line

  // We need a reference to measure the text within its container
  const textRef = React.useRef<Text>(null);

  // --- Logic to check if truncation is necessary ---
  const checkLineCount = useCallback(() => {
    if (!textRef.current) return;

    // 1. Temporarily set maxLines to a high number to get the true line count
    const trueLineCount = textRef.current.measureText(text).lines;

    // 2. Update the state based on the actual count vs. the max allowed lines
    if (trueLineCount > maxLines) {
      setLineCount(trueLineCount);
    } else {
      setLineCount(trueLineCount || 1); // Ensure at least 1
    }
  }, [text, maxLines]);

