  React.useEffect(() => {
    // Use a small timeout to ensure the layout engine has processed the initial render
    const timeout = setTimeout(checkLineCount, 50); 
    return () => clearTimeout(timeout);
  }, [text, checkLineCount]);


  // --- Handlers ---
