        <TouchableOpacity 
          onPress={handleToggle} 
          style={styles.toggleButton}
          activeOpacity={0.7}
        >
          <Text style={styles.toggleText}>{indicatorText}</Text>
        </TouchableOpacity>
      )}
    </View>
  );
